using SimplePZMapmaker.Core;
using System.Text.Json;
public static class RegionAuthoringTests
{
 public static IEnumerable<(string,Action)> Cases(){
  yield return("density regions restore baseline and preserve later manual raster edits",()=>{var p=MapGenerator.Generate(new(){Kind="blank"});p.Zombies[0]=20;var before=JsonSerializer.Serialize(p);var r=new ZombieDensityRegion{X=0,Y=0,Width=8,Height=8,Density=160};var next=ZombieDensityRegions.ApplyProposal(p,[r]);Check(next.Zombies[0]==160&&JsonSerializer.Serialize(p)==before,"Region was not isolated");next.Zombies[0]=71;var moved=ZombieDensityRegions.ApplyProposal(next,[new(){Id=r.Id,X=8,Y=0,Width=8,Height=8,Density=200}]);Check(moved.Zombies[0]==71&&moved.Zombies[1]==200,"Manual edit lost");var clear=ZombieDensityRegions.ApplyProposal(moved,[]);Check(clear.Zombies[0]==71&&clear.Zombies[1]==p.Zombies[1],"Removing region did not restore original raster");});
  yield return("density precedence and 8 tile quantization use actual covered tile centres",()=>{var p=MapGenerator.Generate(new(){Kind="blank"});p.Zombies[0]=0;var a=new ZombieDensityRegion{X=0,Y=0,Width=8,Height=8,Density=64,Order=0};var b=new ZombieDensityRegion{X=0,Y=0,Width=4,Height=8,Density=192,Order=1};var next=ZombieDensityRegions.ApplyProposal(p,[b,a]);Check(next.Zombies[0]==128,"Density overlap was not averaged with ordered precedence");var clear=ZombieDensityRegions.ApplyProposal(next,[]);Check(clear.Zombies[0]==0,"Density baseline was lost");Reject(()=>ZombieDensityRegions.ApplyProposal(p,[new(){X=0,Y=0,Width=8,Height=8,Density=256}]));});
  yield return("native region archive preserves authoring provenance density and actual room aliases",()=>{var p=MapGenerator.Generate(new(){Kind="blank"});p=ZombieDensityRegions.ApplyProposal(p,[new(){X=0,Y=0,Width=8,Height=8,Density=177,SourceTags=new(){["pz:zombie:density"]="177"}}]);var b=new Building{X=20,Y=20,Width=8,Height=8};BuildingDesigner.Generate(b,1,42);var f=b.Design!.Floors[0];f.Cells=new string('0',64);f.Rooms=new(){["0"]="hall"};f.Objects=[];f.Edges=BuildingDesigner.AutoEdges(b,f,0);p.Buildings.Add(b);var rules=new[]{new RoomRegionRule{X=20,Y=20,Width=8,Height=8,RoomName="hotelroom",Selection="contained",SourceTags=new(){["pz:room"]="hotelroom"}}};p=RoomRegionRules.ApplyProposal(p,rules,RoomRegionRules.Preview(p,rules));var bytes=SimplePZMapmaker.Core.Export.NativeMapExporter.Export(p);using var archive=new System.IO.Compression.ZipArchive(new MemoryStream(bytes));using(var source=archive.Entries.Single(e=>e.FullName.EndsWith("project.pzmap.json")).Open()){var restored=JsonSerializer.Deserialize<MapProject>(source,SimplePZMapmaker.Core.Export.NativeMapExporter.JsonOptions)!;Check(restored.ZombieDensityState!.Baseline.Length==1024&&restored.ZombieDensityRegions[0].SourceTags["pz:zombie:density"]=="177"&&restored.RoomRegionRules[0].SourceTags["pz:room"]=="hotelroom","Native archive discarded authoring provenance");}using(var header=new BinaryReader(archive.Entries.Single(e=>e.FullName.EndsWith(".lotheader")).Open())){string Line(){var chars=new List<byte>();byte next;while((next=header.ReadByte())!=10)chars.Add(next);return System.Text.Encoding.ASCII.GetString(chars.ToArray());}Check(System.Text.Encoding.ASCII.GetString(header.ReadBytes(4))=="LOTH","Invalid native header");header.ReadInt32();var tileCount=header.ReadInt32();for(var i=0;i<tileCount;i++)Line();for(var i=0;i<4;i++)header.ReadInt32();var roomCount=header.ReadInt32();var names=new List<string>();for(var i=0;i<roomCount;i++){names.Add(Line());header.ReadInt32();var rects=header.ReadInt32();for(var j=0;j<rects*4;j++)header.ReadInt32();header.ReadInt32();}Check(names.Contains("motelroom")&&!names.Contains("hotelroom"),"Room rule did not use actual native alias");var buildings=header.ReadInt32();for(var i=0;i<buildings;i++){var rooms=header.ReadInt32();for(var j=0;j<rooms;j++)header.ReadInt32();}Check(header.ReadByte()==177,"Density region did not reach native zombie raster");}if(Environment.GetEnvironmentVariable("PZMAP_WORKSPACE")is{} root){var dir=Path.Combine(root,"work","zone-inspect");Directory.CreateDirectory(dir);File.WriteAllBytes(Path.Combine(dir,"native-region-fixture.zip"),bytes);}});
  yield return("room region review ignores unrelated undesigned buildings",()=>{var p=MapGenerator.Generate(new(){Kind="blank"});p.Buildings.Add(new(){X=100,Y=100,Width=8,Height=8});var changes=RoomRegionRules.Preview(p,[new(){X=10,Y=10,Width=8,Height=8,RoomName="storage"}]);Check(changes.Length==0,"Unrelated building selected");});
  yield return("preserve edits reimport retains reversible density regions and reviewed room provenance",()=>{const string data="""{"elements":[{"type":"node","id":1,"lon":32.01,"lat":54.78,"tags":{"amenity":"school"}}]}""";var p=GeographicImporter.Import(data,MapGenerator.Generate(new(){Kind="blank"})).Project;p=ZombieDensityRegions.ApplyProposal(p,[new(){X=0,Y=0,Width=8,Height=8,Density=177,SourceTags=new(){["pz:zombie:density"]="177"}}]);p.RoomRegionRules=[new(){X=20,Y=20,Width=8,Height=8,RoomName="storage",SourceTags=new(){["pz:room"]="storage"}}];p.Zombies[1]=61;var before=JsonSerializer.Serialize(p);var next=GeographicImporter.Import(data,p,p.Bounds,preserveEdits:true).Project;Check(JsonSerializer.Serialize(next.ZombieDensityRegions)==JsonSerializer.Serialize(p.ZombieDensityRegions)&&JsonSerializer.Serialize(next.ZombieDensityState)==JsonSerializer.Serialize(p.ZombieDensityState)&&JsonSerializer.Serialize(next.RoomRegionRules)==JsonSerializer.Serialize(p.RoomRegionRules),"Reimport discarded reversible density or room provenance");Check(!ReferenceEquals(next.ZombieDensityRegions,p.ZombieDensityRegions)&&!ReferenceEquals(next.ZombieDensityState,p.ZombieDensityState),"Reimport shares mutable zone authoring metadata");var cleared=ZombieDensityRegions.ApplyProposal(next,[]);Check(cleared.Zombies[0]==p.ZombieDensityState!.Baseline[0]&&cleared.Zombies[1]==61,"Reimport lost baseline or independent raster edit");Check(JsonSerializer.Serialize(p)==before,"Reimport mutated original project");var replaced=GeographicImporter.Import(data,p,p.Bounds,preserveEdits:false).Project;Check(replaced.ZombieDensityRegions.Count==0&&replaced.ZombieDensityState is null&&replaced.RoomRegionRules.Count==0,"Fresh import retained stale authoring metadata");});
  yield return("room region review changes entire native room and rejects stale review atomically",()=>{var p=MapGenerator.Generate(new(){Kind="blank"});var b=new Building{X=20,Y=20,Width=8,Height=8};BuildingDesigner.Generate(b,1,42);var f=b.Design!.Floors[0];f.Cells=new string('0',64);f.Rooms=new(){["0"]="hall"};f.Objects=[];f.Edges=BuildingDesigner.AutoEdges(b,f,0);p.Buildings.Add(b);var r=new RoomRegionRule{X=20,Y=20,Width=1,Height=1,RoomName="warehouse",SourceTags=new(){["pz:room"]="warehouse",["unsupported:evidence"]="retained"}};var preview=RoomRegionRules.Preview(p,[r]);Check(preview.Length==1&&preview[0].TileCount==64,"Partial room silently selected");var before=JsonSerializer.Serialize(p);Reject(()=>RoomRegionRules.ApplyProposal(p,[r],[]));Check(JsonSerializer.Serialize(p)==before,"Rejected room preview mutated map");var next=RoomRegionRules.ApplyProposal(p,[r],preview);Check(next.Buildings[0].Design!.Floors[0].Rooms["0"]=="warehouse"&&next.RoomRegionRules[0].SourceTags["unsupported:evidence"]=="retained","Whole room/provenance lost");r.Selection="contained";Check(RoomRegionRules.Preview(p,[r]).Length==0,"Contained selection picked partial room");r.RoomName="invented_loot_zone";Reject(()=>RoomRegionRules.Preview(p,[r]));});
 }
 static void Check(bool ok,string message){if(!ok)throw new Exception(message);}static void Reject(Action action){try{action();}catch(ArgumentException){return;}throw new Exception("Invalid region accepted");}
}
